Method.Implementation:
w 0,!
// Get the current inbound request
#dim %request AS %CSP.Request

w 1,!
// make check for application/json content type
if %request.ContentType = "application/json" {
	write "JSON Content Good",!
} else {
	write "JSON Content Bad",!
	zw %request
}

// Make Dynamic Object From Request
set content = ##class(%DynamicObject).%FromJSON(%request.Content)

